notebook = json.loads(original_text)

assert notebook.get("nbformat") == 4, (
    f"Expected nbformat 4, found {notebook.get('nbformat')!r}"
)

cells = notebook.get("cells")
assert isinstance(cells, list), "Notebook does not contain a valid cells list."

existing_markdown = "\n".join(
    "".join(cell.get("source", []))
    for cell in cells
    if isinstance(cell, dict)
)

if MARKER in existing_markdown:
    print("BHA site-wide sweep already present; notebook left unchanged.")
    raise SystemExit(0)

existing_ids = {
    cell.get("id")
    for cell in cells
    if isinstance(cell, dict) and cell.get("id")
}

new_cells = []

for index, report in enumerate(REPORTS, start=1):
    cell = markdown_cell(report, index)

    assert cell["id"] not in existing_ids, (
        f"Notebook already contains cell id {cell['id']!r}."
    )

    new_cells.append(cell)

old_cell_count = len(cells)
notebook["cells"].extend(new_cells)
new_cell_count = len(notebook["cells"])

# Serialize before touching the original file so structural/encoding errors fail
# without changing the notebook.
new_text = json.dumps(
    notebook,
    ensure_ascii=False,
    indent=1,
)
new_text += "\n"

# Re-parse our output before replacement. This protects the existing notebook
# from an accidentally malformed write.
validation = json.loads(new_text)

assert validation.get("nbformat") == 4
assert len(validation["cells"]) == new_cell_count
assert MARKER in "\n".join(
    "".join(cell.get("source", []))
    for cell in validation["cells"]
    if isinstance(cell, dict)
)

fd, temporary_name = tempfile.mkstemp(
    prefix=NOTEBOOK_PATH.name + ".",
    suffix=".tmp",
    dir=NOTEBOOK_PATH.parent,
)

temporary_path = Path(temporary_name)

try:
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        handle.write(new_text)
        handle.flush()
        os.fsync(handle.fileno())

    os.replace(temporary_path, NOTEBOOK_PATH)

finally:
    if temporary_path.exists():
        temporary_path.unlink()

print("BHA SITE-WIDE SWEEP APPENDED")
print("============================")
print("Notebook:", NOTEBOOK_PATH)
print("Existing cells preserved:", old_cell_count)
print("Markdown cells appended:", len(new_cells))
print("New total cell count:", new_cell_count)
print("BHA Authorization read: NO")
print("Network requests made: 0")
print("Database queried: NO")
